// src/core/residence/residence.routes.ts
import { FastifyPluginAsync } from 'fastify';
import { residenceService } from './residence.service';
import { setResidenceSchema, setResidencePreferencesSchema } from './residence.schemas';

const residenceRoutes: FastifyPluginAsync = async (fastify) => {
  /**
   * GET /identity/residence
   * Retorna a residência digital atual do usuário autenticado
   */
  fastify.get('/', async (req, reply) => {
    if (!req.user) {
      return reply.status(401).send({ error: 'Não autenticado' });
    }

    if (!req.user.globalUserId) {
      return reply.status(404).send({ error: 'Identidade global não encontrada' });
    }

    try {
      const residence = await residenceService.getResidenceWithDetails(req.user.globalUserId);

      if (!residence) {
        // Se não tem residência, criar automaticamente a partir do root-config
        await residenceService.autoSetFromRootConfig(req.user.globalUserId);
        const newResidence = await residenceService.getResidenceWithDetails(req.user.globalUserId);
        return newResidence;
      }

      return residence;
    } catch (error) {
      fastify.log.error({ err: error }, 'Erro ao buscar residência');
      return reply.status(500).send({ error: 'Erro ao buscar residência' });
    }
  });

  /**
   * POST /identity/residence/set
   * Define ou atualiza a região da residência digital (país, estado, cidade)
   */
  fastify.post<{
    Body: {
      countryId?: string | null;
      stateId?: string | null;
      cityId?: string | null;
    };
  }>(
    '/set',
    {
      schema: {
        body: {
          type: 'object',
          properties: {
            countryId: { type: ['string', 'null'] },
            stateId: { type: ['string', 'null'] },
            cityId: { type: ['string', 'null'] },
          },
        },
      },
    },
    async (req, reply) => {
      if (!req.user) {
        return reply.status(401).send({ error: 'Não autenticado' });
      }

      if (!req.user.globalUserId) {
        return reply.status(404).send({ error: 'Identidade global não encontrada' });
      }

      try {
        const validated = setResidenceSchema.parse(req.body);
        const residence = await residenceService.setUserResidence(req.user.globalUserId, validated);
        const residenceWithDetails = await residenceService.getResidenceWithDetails(req.user.globalUserId);
        return reply.status(200).send(residenceWithDetails);
      } catch (error) {
        if (error instanceof Error) {
          return reply.status(400).send({ error: error.message });
        }
        return reply.status(500).send({ error: 'Erro ao definir residência' });
      }
    }
  );

  /**
   * POST /identity/residence/set-preferences
   * Define apenas preferências (timezone, currency, languages)
   */
  fastify.post<{
    Body: {
      timezone?: string | null;
      currency?: string;
      languages?: string[];
    };
  }>(
    '/set-preferences',
    {
      schema: {
        body: {
          type: 'object',
          properties: {
            timezone: { type: ['string', 'null'] },
            currency: { type: 'string' },
            languages: {
              type: 'array',
              items: { type: 'string' },
            },
          },
        },
      },
    },
    async (req, reply) => {
      if (!req.user) {
        return reply.status(401).send({ error: 'Não autenticado' });
      }

      if (!req.user.globalUserId) {
        return reply.status(404).send({ error: 'Identidade global não encontrada' });
      }

      try {
        const validated = setResidencePreferencesSchema.parse(req.body);
        await residenceService.setResidencePreferences(req.user.globalUserId, validated);
        const residenceWithDetails = await residenceService.getResidenceWithDetails(req.user.globalUserId);
        return reply.status(200).send(residenceWithDetails);
      } catch (error) {
        if (error instanceof Error) {
          return reply.status(400).send({ error: error.message });
        }
        return reply.status(500).send({ error: 'Erro ao definir preferências' });
      }
    }
  );
};

export default residenceRoutes;
















